import test from 'node:test';import assert from 'node:assert/strict';import {Element} from './helpers/panel-dom.js';import {savedRehearsalGuideFixtures,until} from './helpers/workspace-fixtures.js';import {mountSavedFileInspectionPanel} from '../examples/file-read-panel.js';
const before=savedRehearsalGuideFixtures()[0].text,after=JSON.stringify(JSON.parse(before))+'\r\n';
async function setup(){const parent=new Element('div'),document={createElement:tag=>new Element(tag)},downloads=[],panel=mountSavedFileInspectionPanel({document,parent,download:value=>downloads.push(value)}),q=name=>parent.find('saved-bundle-'+name);await panel.inspectFile(new File([before],'before.json'));await panel.compareFile(new File([after],'after.json'));return{panel,q,downloads,ack(name){q(name).checked=true;q(name).dispatchEvent(new Event('change'));},async load(text){q('file').files=[new File([text],'bundle.json')];q('file').dispatchEvent(new Event('change'));await until(()=>q('stop').disabled);}};}
test('combined guide packs plain sources only after acknowledgement and extracts each exact file separately',async()=>{
 const f=await setup();try{assert(!f.q('export-ack').disabled);assert(f.q('export').disabled);f.ack('export-ack');f.q('export').click();await until(()=>f.q('stop').disabled);assert.equal(f.downloads.length,1);const bundle=f.downloads[0].text;assert.equal(JSON.parse(bundle).schema,'threecore.saved-file-comparison-bundle.v2');await f.load(bundle);assert.match(f.q('output').textContent,/内部チェックサムのない/);assert(f.q('before').disabled);f.ack('source-ack');f.q('before').click();assert.equal(f.downloads.at(-1).text,before);assert(f.q('after').disabled);f.ack('source-ack');f.q('after').click();assert.equal(f.downloads.at(-1).text,after);assert.equal(f.downloads.at(-1).simulationOnly,true);}finally{f.panel.dispose();}
});
test('a plain-source comparison mismatch leaves both extraction controls disabled',async()=>{
 const f=await setup();try{f.ack('export-ack');f.q('export').click();await until(()=>f.q('stop').disabled);const bundle=JSON.parse(f.downloads[0].text),comparison=JSON.parse(bundle.comparisonText);comparison.sourceTextComparison.sameText=true;bundle.comparisonText=JSON.stringify(comparison);await f.load(JSON.stringify(bundle));assert(f.q('source-ack').disabled);assert(f.q('before').disabled);assert(f.q('after').disabled);assert.match(f.q('output').textContent,/不一致/);assert.equal(f.downloads.length,1);}finally{f.panel.dispose();}
});
